#!/usr/bin/env python3
"""Per-run synthetic credentials for security tests.

A security test may need a value that looks like a credential. It must never
borrow one from the user's environment, session database, history or Memory:
those are real secrets, and a test that accepts them turns a security check into
a second disclosure. This module is the one source tests may use.

The contract, enforced here rather than by convention:

* A value is generated by THIS process for THIS run, from `secrets`.
* The run id plus an in-memory issued set is the provenance. A value copied
  from anywhere else — an env var, a session row, a fixture, another run — is
  rejected even if it "looks random".
* Manifests and reports carry only a SHA-256 digest prefix, never the value.
* `redact()` lets a test replace the value in its own evidence with a stable
  placeholder, so a failed assertion cannot print it.

This is test infrastructure, not a product credential path. It grants no
provider or tool permission; a synthetic value has no business authority.
"""

from __future__ import annotations

import hashlib
import re
import secrets
import uuid

_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
_PREFIX_RE = re.compile(r"^CLTEST-([0-9a-f]{8})-[a-z0-9-]+-[A-Za-z0-9]{32,}$")


class UntrustedCanary(ValueError):
    """A value that did not come from this run's generator."""


class SyntheticCanaryRun:
    """The only accepted source of security-test credential values."""

    def __init__(self, purpose: str):
        self.run_id = uuid.uuid4().hex[:8]
        self.purpose = purpose
        self._issued: dict[str, str] = {}
        self._labels: dict[str, str] = {}

    def issue(self, label: str) -> str:
        """Generate one fresh synthetic value for `label`."""
        if not re.fullmatch(r"[a-z0-9-]{1,32}", label):
            raise ValueError("canary label must be short lowercase ascii")
        token = "".join(secrets.choice(_ALPHABET) for _ in range(40))
        value = f"CLTEST-{self.run_id}-{label}-{token}"
        digest = self.digest(value)
        if digest in self._issued:
            # Astronomically unlikely; a collision must never merge two labels.
            raise RuntimeError("synthetic canary digest collision")
        self._issued[digest] = label
        self._labels[label] = digest
        return value

    def accepts(self, value: str) -> bool:
        """Whether `value` was issued by this run and nothing else."""
        if not isinstance(value, str):
            return False
        match = _PREFIX_RE.fullmatch(value)
        if not match or match.group(1) != self.run_id:
            return False
        return self._issued.get(self.digest(value)) is not None

    def require(self, value: str) -> str:
        """The gate a test calls before sending the value anywhere."""
        if not self.accepts(value):
            raise UntrustedCanary(
                "refusing a security-test credential that did not come from this run; "
                "generate it with SyntheticCanaryRun.issue()"
            )
        return value

    def label_of(self, value: str) -> str | None:
        if not self.accepts(value):
            return None
        return self._issued.get(self.digest(value))

    def digest(self, value: str) -> str:
        return hashlib.sha256(value.encode("utf-8")).hexdigest()[:12]

    def manifest(self) -> dict:
        """Report-safe provenance: digests and labels, never values."""
        return {
            "purpose": self.purpose,
            "run_id": self.run_id,
            "source": "synthetic_canary.py:secrets",
            "issued": [
                {"label": self._issued[digest], "digest": digest}
                for digest in sorted(self._issued)
            ],
        }

    def redactions(self) -> dict[str, str]:
        """Stable placeholders for evidence, keyed by the value itself."""
        return {label: f"<SYNTHETIC-{label.upper()}>" for label in self._labels}

    def scrub(self, text: str, value: str, placeholder: str) -> str:
        self.require(value)
        if not placeholder.startswith("<SYNTHETIC-"):
            raise ValueError("redaction placeholders must be visibly synthetic")
        return text.replace(value, placeholder)


# A process-wide run for scripts that issue once. Tests that need isolation
# create their own instance.
_default_run: SyntheticCanaryRun | None = None


def default_run(purpose: str) -> SyntheticCanaryRun:
    global _default_run
    if _default_run is None:
        _default_run = SyntheticCanaryRun(purpose)
    return _default_run
